package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaMlDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_jar_su" to DuaText("ഒരു മോശം അയൽക്കാരിൽ നിന്നുള്ള അഭയം", "അല്ലാഹുവേ, സ്ഥിരതാമസമുള്ള ഒരു മോശം അയൽക്കാരിൽ നിന്ന് ഞാൻ നിന്നിൽ അഭയം തേടുന്നു, കാരണം യാത്രയിലുള്ള അയൽക്കാരൻ മുന്നോട്ട് പോകുന്നു.", "ഒരു മോശം അയൽക്കാരിൽ നിന്നുള്ള സംരക്ഷണത്തിനായി.", "ഇതിൽ നിന്ന് അഭയം തേടാൻ പ്രവാചകൻ സൽഹഅലിഹ് വസ്ൽമ കൽപിച്ചു."),
        "dua_ishfi_abdak" to DuaText("രോഗിയായ ഒരാളുടെ രോഗമുക്തിക്ക്", "അല്ലാഹുവേ, നിൻറെ ദാസൻ നിനക്കുവേണ്ടി ഒരു ശത്രുവിനെ നേരിടാനോ നിനക്കുവേണ്ടി പ്രാർത്ഥിക്കാനോ വേണ്ടി അവനെ സുഖപ്പെടുത്തണമേ.", "രോഗിയായ വ്യക്തിയെ സന്ദർശിക്കുമ്പോൾ.", "രോഗികൾക്ക് വേണ്ടി ഇത് പറയാനാണ് പ്രവാചകൻ പഠിപ്പിച്ചത്."),
        "dua_la_mania" to DuaText("നിങ്ങൾ നൽകുന്നത് ആർക്കും തടയാൻ കഴിയില്ല.", "അല്ലാഹുവല്ലാതെ ആരാധനയ്ക്ക് അർഹനായി മറ്റാരുമില്ല. അവൻ ഏകനാണ്, അവന് പങ്കാളികളില്ല. അവന്നാകുന്നു ആധിപത്യം. അവന്നാകുന്നു സ്തുതി. അവനാണ് എല്ലാറ്റിൻ്റെയും മേൽ അധികാരം. അല്ലാഹുവേ, നീ നൽകുന്നത് ആർക്കും തടഞ്ഞുവെക്കാൻ കഴിയില്ല. നീ തടഞ്ഞുവെക്കുന്നത് ആർക്കും നൽകാൻ കഴിയില്ല. ധനികരുടെ സമ്പത്ത് നിനക്കെതിരെ ഒരു പ്രയോജനവുമില്ല.", "നിർബന്ധിത പ്രാർത്ഥനയുടെ നമസ്കാരത്തിനുശേഷം.", "എല്ലാ നിർബന്ധിത പ്രാർത്ഥനയ്ക്കും ശേഷം പ്രവാചകൻ (സ) പറഞ്ഞു."),
        "dua_slaughtering" to DuaText("ഒരു മൃഗത്തെ കൊല്ലുമ്പോൾ", "അല്ലാഹുവിൻറെ നാമത്തിൽ, അല്ലാഹു ഏറ്റവും വലിയവനാണ്.", "ഒരു മൃഗത്തെ ബലിയർപ്പിക്കുകയോ അറുക്കുകയോ ചെയ്യുമ്പോൾ.", "നബി (സ) ബിസ്മില്ലയും തക്ബീറും യാഗസമയത്ത് പറഞ്ഞിട്ടുണ്ട്."),
        "dua_undressing" to DuaText("വസ്ത്രങ്ങൾ ഊരിയെടുക്കുമ്പോൾ", "അല്ലാഹുവിൻറെ നാമത്തിൽ.", "വസ്ത്രങ്ങൾ ഊരിയെടുക്കുമ്പോൾ (കുളിക്കാനോ മാറ്റാനോ).", "ഇത് ജിന്നുകളുടെ കണ്ണുകൾക്കും ഒരു വ്യക്തിയുടെ സ്വകാര്യഭാഗങ്ങൾക്കും ഇടയിലുള്ള ഒരു സ്ക്രീനായി മാറുന്നു."),
        "dua_ilbas_jadidan" to DuaText("പുതിയ വസ്ത്രങ്ങൾ ധരിച്ച ആരെയെങ്കിലും കാണുക", "പുതിയതായി ധരിക്കുക, അഭിനന്ദനാർഹമായി ജീവിക്കുക, രക്തസാക്ഷിയായി മരിക്കുക.", "പുതിയ വസ്ത്രത്തിൽ ഒരു മുസ്ലീം സഹോദരനെ കണ്ടപ്പോൾ.", "ഉമർ (റ) നെ പുതിയ വസ്ത്രത്തിൽ കണ്ടാണ് പ്രവാചകൻ (സ) ഈ ദുആ ചെയ്തത്."),
        "dua_hajj_la_riya" to DuaText("പ്രദർശനത്തിൽ നിന്ന് മുക്തമായ ഹജ്ജ്", "അല്ലാഹുവേ, (അതിനെ) ഒരു ഹജ്ജ് ആക്കുക, അതിൽ ഒരു പ്രകടനവും പ്രശസ്തിയും ഇല്ല.", "ഹജ്ജ് ഉദ്ദേശിക്കുമ്പോൾ ആത്മാർത്ഥതയ്ക്ക്.", "ഹജ്ജ് സമയത്ത് പ്രവാചകൻ സൽഹുല്ലാഹൽ മുസ്ലിമാണ് ഈ ദുആ നടത്തിയത്."),
        "dua_q_muslimayni_laka" to DuaText("ഇബ്രാഹിമിൻ്റെയും ഇസ്മായിലിൻ്റെയും (എ. എസ്.) ദുആ-ഞങ്ങളെ വിധേയരാക്കുക", "ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങൾ നിന്നോട് കീഴ്പെടുന്നവരും ഞങ്ങളുടെ സന്തതികളിൽ നിന്ന് നിന്നോട് കീഴ്പെടുന്നവരുമായ ഒരു ജനതയായി ഞങ്ങളെ മാറ്റണമേ. ഞങ്ങളുടെ ആരാധനയുടെ ആചാരങ്ങൾ ഞങ്ങൾക്ക് കാണിച്ചുതരേണമേ. ഞങ്ങളുടെ പശ്ചാത്താപം സ്വീകരിക്കണമേ. തീർച്ചയായും നീ പശ്ചാത്താപത്തിൻറെ ഉടമയും കരുണാനിധിയുമാകുന്നു.", "തനിക്കും സ്വന്തം പിൻഗാമികൾക്കും വേണ്ടിയുള്ള ഒരു സമർപ്പണത്തിൻ്റെ ദ്വയം.", "കാബാ നിർമ്മിക്കുമ്പോഴാണ് ദുആ നിർമ്മിച്ചത്."),
        "dua_q_iftah_baynana" to DuaText("ഷുഐബിൻറെ ദുആ (എ. എസ്)-ഞങ്ങൾക്കിടയിൽ ന്യായാധിപൻ", "ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങൾക്കും ഞങ്ങളുടെ ജനങ്ങൾക്കും ഇടയിൽ നീ സത്യസന്ധമായി വിധിക്കേണമേ. നീയാണ് വിധികർത്താക്കളിൽ ഏറ്റവും നല്ലവൻ.", "സത്യവും അസത്യവും തമ്മിലുള്ള ഒരു വിധിക്കായി.", "ഷുഐബിൻറെ (അ. സ.) ജനങ്ങൾ അദ്ദേഹത്തെ നിരസിച്ചപ്പോൾ അദ്ദേഹത്തിൻറെ ദുആ."),
        "dua_q_la_akuna_zahiran" to DuaText("മൂസയുടെ ദുആ (എ. എസ്)-ഒരിക്കലും കുറ്റവാളികളുടെ സഹായിയല്ല", "എൻറെ രക്ഷിതാവേ, നീ എനിക്ക് നൽകിയ അനുഗ്രഹം കാരണം ഞാൻ ഒരിക്കലും കുറ്റവാളികളുടെ സഹായിയാകില്ല.", "അല്ലാഹുവിൻറെ അനുഗ്രഹങ്ങൾക്ക് നന്ദിയും അക്രമികളെ സഹായിക്കില്ലെന്ന് പ്രതിജ്ഞയും.", "മൂസാ (അ. സ.) യുടെ അനുതാപത്തിനുശേഷമുള്ള പ്രതിജ്ഞ."),
        "dua_q_nuh_unsurni" to DuaText("നൂഹ് (അ. സ.)-എന്നെ സഹായിക്കൂ, അവർ എന്നെ നിഷേധിക്കുന്നു.", "എൻറെ രക്ഷിതാവേ, എന്നെ സഹായിക്കേണമേ; അവർ എന്നെ നിഷേധിച്ചു.", "ആളുകൾ നിങ്ങളെ നിഷേധിക്കുകയും സത്യം നിരസിക്കുകയും ചെയ്യുമ്പോൾ.", "നൂഹിൻറെ (അ. സ.) ദുആ, അതിന് ഉത്തരം നൽകപ്പെട്ടു."),
        "dua_q_ihkum_bil_haqq" to DuaText("എൻറെ കർത്താവേ, സത്യത്തോടെ വിധിക്കണമേ.", "എൻറെ രക്ഷിതാവേ, നീ സത്യത്തോടെ വിധി വിധിക്കേണമേ. ഞങ്ങളുടെ രക്ഷിതാവ് പരമകാരുണികനാണ്. നീ വിവരിക്കുന്നതിൽനിന്ന് അവൻറെ സഹായം തേടപ്പെടുന്നു.", "നുണകൾക്കും വ്യാജ ആരോപണങ്ങൾക്കും മുന്നിൽ.", "നബി (സ) യെ ഒരു ദുആ പഠിപ്പിച്ചു."),
        "dua_ghalabatid_dayn" to DuaText("കടം തകർക്കുന്നതിൽ നിന്നും ശത്രുക്കളിൽ നിന്നും അഭയം", "അല്ലാഹുവേ, കടബാധ്യതകളാൽ മുഷിഞ്ഞുപോകുന്നതിൽ നിന്നും ശത്രുക്കളുടെ സ്വാധീനത്തിൽ നിന്നും ശത്രുക്കളുടെ അഹങ്കാരത്തിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "കടത്തിന്റെ ഭാരത്തിൽ നിന്നും ശത്രുക്കളുടെ ആധിപത്യത്തിൽ നിന്നും സംരക്ഷണം.", "നബി (സ) ഇവയിൽ നിന്ന് അഭയം തേടാറുണ്ടായിരുന്നു."),
        "dua_faqr_qillah_dhillah" to DuaText("ദാരിദ്ര്യത്തിൽ നിന്നും അപമാനത്തിൽ നിന്നും അഭയം", "അല്ലാഹുവേ, ദാരിദ്ര്യത്തിൽ നിന്നും ക്ഷാമത്തിൽ നിന്നും അപമാനത്തിൽ നിന്നും മറ്റുള്ളവരോട് അനീതി കാണിക്കുന്നതിൽ നിന്നും അനീതി ചെയ്യപ്പെടുന്നതിലും നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "കഷ്ടപ്പാടുകളിൽ നിന്നും ആഗ്രഹങ്ങളിൽ നിന്നും അപമാനത്തിൽ നിന്നും സുരക്ഷിതരായിരിക്കുക.", "നബി (സ) പഠിപ്പിച്ച ഒരു അഭയസ്ഥാനം."),
        "dua_five_things_new_muslim" to DuaText("ക്ഷമിക്കുക, കരുണ കാണിക്കുക, നയിക്കുക, സുഖപ്പെടുത്തുക, നൽകുക", "അല്ലാഹുവേ, എന്നോട് ക്ഷമിക്കണമേ, എന്നോട് കരുണ കാണിക്കണമേ, എന്നെ നയിക്കണമേ, എനിക്ക് ക്ഷേമം നൽകണമേ, എനിക്ക് ഉപജീവനം നൽകണമേ.", "നബിയായ സൽഹഅലിഹ് വസ്ലം പുതിയ മുസ്ലീങ്ങളെ പ്രാർത്ഥനയ്ക്കൊപ്പം ഈ ദുആ പഠിപ്പിച്ചു.", "നബി (സ) പറഞ്ഞുഃ ഈ വാക്കുകൾ നിങ്ങൾക്കായി ഈ ലോകവും പരലോകവും ശേഖരിക്കുന്നു."),
        "dua_ruku_laka_raka_tu" to DuaText("റുക്കുവിൽ-ഞാൻ നിന്നെ വണങ്ങി", "അല്ലാഹുവേ, ഞാൻ നിന്നെ വണങ്ങി. ഞാൻ നിന്നിൽ വിശ്വസിച്ചു. ഞാൻ നിനക്ക് കീഴ്പ്പെട്ടിരിക്കുന്നു. എൻറെ കേൾവിയും കാഴ്ചയും മനസ്സും എല്ലുകളും ഞെരുക്കവും നിൻറെ മുമ്പിൽ താഴ്ത്തപ്പെട്ടിരിക്കുന്നു.", "റുക്കുവിൽ (പ്രത്യേകിച്ച് സ്വമേധയാ പ്രാർത്ഥനകളിൽ).", "നബി (സ) ഇത് റുക്കുവിൽ പാരായണം ചെയ്തു."),
        "dua_sujood_laka_sajadtu" to DuaText("സുജൂദിൽ-ടു യു ഞാൻ പ്രൊസ്റ്റ്രേറ്റ് ചെയ്തു", "അല്ലാഹുവേ, ഞാൻ നിന്നെ സാഷ്ടാംഗം നമസ്കരിച്ചു. ഞാൻ നിന്നിൽ വിശ്വസിക്കുകയും, ഞാൻ നിന്നിൽ കീഴടങ്ങുകയും ചെയ്തു. അതിനെ സൃഷ്ടിച്ചവനും രൂപപ്പെടുത്തിയവനും, കേൾവിയും കാഴ്ചയും നൽകിയവനും എന്റെ മുഖം സാഷ്ടാംഗം നമസ്കരിക്കുകയും ചെയ്തു. സൃഷ്ടാക്കളിൽവെച്ച് ഏറ്റവും നല്ലവനായ അല്ലാഹു അനുഗ്രഹിക്കപ്പെട്ടവനാകുന്നു.", "സുജൂദിൽ (പ്രത്യേകിച്ച് സ്വമേധയാ പ്രാർത്ഥനകളിൽ).", "നബി (സ) സുജൂദിൽ ഇത് പാരായണം ചെയ്തു."),
        "dua_ruku_sujood_subhanaka" to DuaText("ഞങ്ങളുടെ കർത്താവേ, അങ്ങേയ്ക്ക് മഹത്വം ഉണ്ടാകട്ടെ-എന്നോട് ക്ഷമിക്കണമേ.", "ഞങ്ങളുടെ രക്ഷിതാവായ അല്ലാഹുവേ, നിനക്ക് മഹത്വവും സ്തുതി നിനക്ക് തന്നെ. അല്ലാഹുവേ, എന്നോട് നീ പൊറുത്തുതരേണമേ.", "റുക്കുവിലും സുജൂദിലും.", "ആയിഷ (റ): നബി (സ) പലപ്പോഴും ഇത് രുകുവിലും സുജൂദിലും പറഞ്ഞിട്ടുണ്ട്."),
        "dua_q_musa_li_akhi" to DuaText("മൂസയുടെ ദുആ (എ. എസ്)-എന്നോടും എൻറെ സഹോദരനോടും ക്ഷമിക്കണമേ.", "എൻറെ രക്ഷിതാവേ, എന്നോടും എൻറെ സഹോദരനോടും നീ പൊറുത്തുതരേണമേ. ഞങ്ങളെ നിൻറെ കാരുണ്യത്തിൽ പ്രവേശിപ്പിക്കണമേ. നീ കാരുണ്യക്കാരിൽ ഏറ്റവും കരുണാനിധിയാണ്.", "തനിക്കും സ്വന്തം സഹോദരനോടോ പ്രിയപ്പെട്ടവർക്കോടോ ഉള്ള ക്ഷമ.", "ഹാറൂൺ (എ. എസ്) എന്നതിന് മൂസ (എ. എസ്) യുടെ ദുആ."),
        "dua_q_ufawwidu_amri" to DuaText("ഞാൻ എൻ്റെ കാര്യം അല്ലാഹുവിന് സമർപ്പിക്കുന്നു.", "ഞാൻ എൻറെ കാര്യം അല്ലാഹുവിന് സമർപ്പിക്കുകയും ചെയ്യുന്നു. തീർച്ചയായും അല്ലാഹു തൻറെ ദാസന്മാരെ എല്ലാം കാണുന്നവനല്ലോ.", "ആളുകൾ നിങ്ങളെ എതിർക്കുമ്പോൾ, വിഷയം അല്ലാഹുവിന് വിട്ടുകൊടുക്കണം.", "ഫറവോൻറെ ജനതയിൽ നിന്നുള്ള വിശ്വാസിയുടെ വാക്കുകൾ; അപ്പോൾ അവരുടെ ദുഷിച്ച ഗൂഢാലോചനകളിൽ നിന്ന് അല്ലാഹു അദ്ദേഹത്തെ സംരക്ഷിച്ചു."),
        "dua_q_hawariyyun" to DuaText("ശിഷ്യന്മാരുടെ ദുആ-സാക്ഷികളോടൊപ്പം ഞങ്ങളെ രേഖപ്പെടുത്തുക", "ഞങ്ങളുടെ രക്ഷിതാവേ, നീ അവതരിപ്പിച്ചതിൽ ഞങ്ങൾ വിശ്വസിക്കുകയും, ദൂതനെ പിന്തുടരുകയും ചെയ്തിരിക്കുന്നു. അതിനാൽ ഞങ്ങളെ സാക്ഷികളുടെ കൂട്ടത്തിൽ രേഖപ്പെടുത്തുക.", "വിശ്വാസത്തിലും ദൂതനെ പിന്തുടരുന്നതിലും സ്ഥിരത പുലർത്തുന്നതിനായി.", "ഈസയുടെ (എ. എസ്) ശിഷ്യന്മാരുടെ ദുആ."),
        "dua_q_la_tukhzini" to DuaText("ഇബ്രാഹിം (അ. സ.)-എന്നെ അപമാനിക്കരുത്.", "അവർ ഉയിർത്തെഴുന്നേൽപിക്കപ്പെടുന്ന ദിവസം എന്നെ നിങ്ങൾ അപമാനിക്കരുത്.", "ഉയിർത്തെഴുന്നേൽപിൻറെ നാളിൽ അപമാനത്തിൽ നിന്ന് സുരക്ഷിതരായിരിക്കാൻ.", "ഇബ്രാഹിമിൻറെ (അ. സ.) പരലോകത്തെ ദൈവസാന്നിധ്യം."),
        "dua_iftar_laka_sumtu" to DuaText("ഇഫ്താർ-നിങ്ങൾക്കായി ഞാൻ ആസ്വദിച്ചു", "അല്ലാഹുവേ, ഞാൻ നിനക്കുവേണ്ടി നോമ്പ് അനുഷ്ഠിക്കുകയും നിൻറെ ഉപജീവനമാർഗം കൊണ്ട് എൻറെ നോമ്പ് ലംഘിക്കുകയും ചെയ്യുന്നു.", "നോമ്പ് (അറിയപ്പെടുന്ന ഇഫ്താർ ദുആ) ലംഘിക്കുമ്പോൾ.", "ഇഫ്താരിൽ പ്രവാചകൻ സൽഹഅലിഹ് വസ്ലം ഇത് പറഞ്ഞു. മറ്റ് വിവരണങ്ങളാൽ ശക്തിപ്പെട്ട ഒരു ഖുർസാൽ വിവരണമാണിത്; ഇഫ്താരിൽ അത് പാരായണം ചെയ്യുന്നത് ഹനഫികളുടെയും ഭൂരിപക്ഷത്തിന്റെയും ആചാരമാണ്."),
        "dua_iftar_ibn_umar" to DuaText("ഇഫ്താർ-നിൻറെ വിശാലമായ കരുണയിലൂടെ, എന്നോട് ക്ഷമിക്കണമേ.", "അല്ലാഹുവേ, എന്നോട് ക്ഷമിക്കാൻ സകലവും ഉൾക്കൊള്ളുന്ന നിൻറെ കാരുണ്യത്താൽ ഞാൻ നിന്നോടു അപേക്ഷിക്കുന്നു.", "ഇഫ്താരിൽ-അബ്ദുല്ല ഇബ്നു അംർ (റ) ഈ ദുആ ഉണ്ടാക്കി; ഇഫ്താരിൽ ഉപവാസം ചെയ്യുന്ന വ്യക്തിയുടെ ദുആ നിരസിക്കപ്പെടുന്നില്ല.", "ഹദീസ്ഃ ഇഫ്താർ സമയത്ത് ഉപവാസം ചെയ്യുന്ന വ്യക്തിയുടെ ദുആ നിരസിക്കപ്പെടുന്നില്ല."),
        "dua_inni_saim" to DuaText("ഉപവാസം ചെയ്യുമ്പോൾ പ്രകോപിപ്പിക്കപ്പെടുമ്പോൾ", "ഞാൻ ഉപവാസം ചെയ്യുന്നു, ഞാൻ ഉപവാസം ചെയ്യുന്നു.", "ഉപവാസത്തിനിടയിൽ ആരെങ്കിലും നിങ്ങളെ അപമാനിക്കുകയോ നിങ്ങളുമായി തർക്കിക്കുകയോ ചെയ്യുമ്പോൾ.", "നബി (സ) പറഞ്ഞുഃ നോമ്പ് ഒരു പരിചയാണ്, അതിനാൽ നോമ്പ് അനുഷ്ഠിക്കുന്ന വ്യക്തി അശ്ലീലമായി സംസാരിക്കാനോ അജ്ഞതയോടെ പ്രവർത്തിക്കാനോ പാടില്ല-ആരെങ്കിലും തർക്കിക്കുകയാണെങ്കിൽ ഇത് രണ്ടുതവണ പറയുക."),
        "dua_eid_takbeer" to DuaText("ഈദിനിലേക്കുള്ള വഴിയിൽ തക്ബീർ", "അല്ലാഹു ഏറ്റവും വലിയവനാണ്, അല്ലാഹു ഏറ്റവും വലിയവനാണ്, അല്ലാഹുവല്ലാതെ ദൈവമില്ല, അല്ലാഹു ഏറ്റവും വലിയവനാണ്, അല്ലാഹു ഏറ്റവും വലിയവനാണ്, എല്ലാ സ്തുതികളും അല്ലാഹുവിനാണ്.", "ചന്ദ്രഗ്രഹണത്തിന്റെ രാത്രി മുതൽ ഈദ് അൽ-ഫിത്തർ പ്രാർത്ഥന വരെ, പ്രത്യേകിച്ച് ഈദ് ഗ്രൌണ്ടിലേക്കുള്ള വഴിയിൽ.", "ഖുർആൻ കൽപ്പനഃ'നിങ്ങൾ കണക്ക് പൂർത്തിയാക്കി അല്ലാഹുവിന്റെ മഹത്വം പ്രഖ്യാപിക്കാൻ'(അൽ-ബഖറ 2:185). ഇബ്നു മസൂദ് (റ) ഈ തക്ബീർ പറഞ്ഞു."),
        "dua_ahsin_aqibatana" to DuaText("എല്ലാ കാര്യങ്ങളിലും നമ്മുടെ അന്ത്യം നന്നായിരിക്കട്ടെ", "അല്ലാഹുവേ, എല്ലാ കാര്യങ്ങളിലും ഞങ്ങളുടെ ലക്ഷ്യം നന്നാക്കേണമേ. ഇഹലോകത്തെ അപമാനത്തിൽ നിന്നും പരലോകത്തെ ശിക്ഷയിൽ നിന്നും ഞങ്ങളെ സംരക്ഷിക്കണമേ.", "എല്ലാ കാര്യങ്ങളിലും നല്ല ഫലത്തിന്.", "വിചാരണ നേരിടുന്നതിന് മുമ്പ് ഈ ദുആ ചെയ്ത് മരിക്കുന്നവൻ മരിക്കുന്നു (വിചാരണയ്ക്കുശേഷം സുരക്ഷിതൻ)."),
        "dua_fadlika_wa_rahmatik" to DuaText("ഞാൻ അങ്ങയുടെ അനുഗ്രഹവും കരുണയും ചോദിക്കുന്നു.", "അല്ലാഹുവേ, നിന്നോട് ഞാൻ നിൻറെ അനുഗ്രഹവും കാരുണ്യവും യാചിക്കുന്നു. നിങ്ങളല്ലാതെ മറ്റാർക്കും അവയുടെ അവകാശമില്ല.", "ഉപജീവനവും ദയയും ചോദിക്കുമ്പോൾ.", "ഭക്ഷണം ഇല്ലാതിരുന്നപ്പോൾ അതിഥികൾ പ്രവാചകൻറെ അടുത്ത് വന്നു; അദ്ദേഹം ഈ ദുആ ഉണ്ടാക്കി, തുടർന്ന് ഒരു സമ്മാനം വന്നു."),
        "dua_allahu_akbar_kabira_2696" to DuaText("ഒരു ബെഡൂയിനെ പഠിപ്പിച്ച വാക്കുകൾ", "അല്ലാഹുവല്ലാതെ ആരാധിക്കപ്പെടാൻ ആർക്കും അവകാശമില്ല. അല്ലാഹുവല്ലാതെ, പങ്കാളിയില്ലാതെ. അല്ലാഹു ഏറ്റവും വലിയവനും, അല്ലാഹുവിന് വിപുലമായ സ്തുതിയുമാണ്. ലോകരക്ഷിതാവായ അല്ലാഹുവിന് മഹത്വമുണ്ട്. സർവ്വശക്തനും യുക്തിമാനുമായ അല്ലാഹുവല്ലാതെ ശക്തിയോ ശക്തിയോ ഇല്ല.", "ഒരു ബെഡൂയിൻ പഠിപ്പിച്ച ധിക്കറിന്റെയും ദുആയുടെയും സമഗ്രമായ ഒരു വാചകം.", "ഇതിനുശേഷം'അല്ലാഹുമ്മഗ്ഫിർ ലി വാർഹമ്നി വാഹ്ദിനി വാർസുഖ്നി'എന്ന് പറയാൻ അദ്ദേഹത്തെ പഠിപ്പിച്ചു."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("മുമ്പും ശേഷവും ഞാൻ അയച്ച കാര്യങ്ങൾ ക്ഷമിക്കണം.", "അല്ലാഹുവേ, ഞാൻ മുമ്പും ശേഷവും ചെയ്ത പാപങ്ങളും, ഞാൻ രഹസ്യമായി ചെയ്തതും പരസ്യമായി ചെയ്തതും, എന്റെ അതിക്രമങ്ങളും, എന്നെക്കാൾ നന്നായി നീ അറിയുന്ന കാര്യങ്ങളും എന്നോട് ക്ഷമിക്കണമേ. നീയാണ് മുന്നോട്ട് കൊണ്ടുപോകുന്നവനും തിരിച്ചുകൊടുക്കുന്നവനും. നിന്നല്ലാതെ ദൈവമില്ല.", "താഷാഹുദിനും സലാവത്തിനും ശേഷം സലാമിന് മുമ്പ്.", "പ്രാർത്ഥനയുടെ അവസാനത്തിൽ, താഷാഹുദിനും സലാമിനുമിടയിൽ പ്രവാചകൻ സൽഹഅലിഹ് വസ്ലം ഇത് പാരായണം ചെയ്തു."),
        "dua_jiddi_wa_hazli" to DuaText("എൻ്റെ ഗൌരവത്തോടും പരിഹാസത്തോടും ക്ഷമിക്കുക.", "അല്ലാഹുവേ, ഞാൻ ഗുരുതരമായും തമാശയായും അബദ്ധത്തിലും മനപ്പൂർവ്വമായും ചെയ്ത പാപങ്ങൾ എന്നോട് ക്ഷമിക്കണമേ-അതെല്ലാം എന്നിലുണ്ട്.", "അറിയപ്പെടുന്നതും അറിയപ്പെടാത്തതുമായ എല്ലാത്തരം പാപങ്ങൾക്കും ക്ഷമ.", "നബി (സ) യുടെ സമഗ്രമായ ഒരു ഇസ്തിഗ്ഫർ."),
        "dua_rising_ruku_mil" to DuaText("രുകുവിന് ശേഷം-സ്വർഗ്ഗം നിറയ്ക്കുക", "ഞങ്ങളുടെ രക്ഷിതാവേ, ആകാശങ്ങൾ നിറയ്ക്കുകയും, ഭൂമി നിറയ്ക്കുകയും, അതിനുശേഷം നീ ഉദ്ദേശിക്കുന്നതെന്തും നിറയ്ക്കുകയും ചെയ്യുന്ന എല്ലാ സ്തുതിയും നിനക്കുള്ളതാണ്.", "റുക്കുവിൽ നിന്ന് ഉയർന്നുവന്ന ശേഷം'റബ്ബന ലാകൽ-ഹംദ്'എന്ന ചിത്രത്തോടൊപ്പം.", "റുക്കുവിൽ നിന്ന് എഴുന്നേറ്റപ്പോഴാണ് പ്രവാചകൻ സൽഹഅലിഹ് വസ്ലം ഇത് പറഞ്ഞത്."),
        "dua_istiftah_kabira" to DuaText("അല്ലാഹു ഏറ്റവും വലിയവനും സ്തുത്യർഹനുമാണ്.", "അല്ലാഹു ഏറ്റവും വലിയവനും, മഹത്തായവനും, അല്ലാഹുവിന് വിപുലമായ സ്തുതിയും, രാവിലെയും വൈകുന്നേരവും അല്ലാഹുവിന് മഹത്വവുമുണ്ട്.", "പ്രാർത്ഥന ആരംഭിക്കുമ്പോൾ (ഉദ്ഘാടന സ്തുതിയുടെ ഒരു രൂപം).", "നബി (സ) പറഞ്ഞുഃ സ്വർഗ്ഗത്തിൻറെ കവാടങ്ങൾ അതിനായി തുറക്കപ്പെട്ടു."),
        "dua_q_ashku_bathhi" to DuaText("യാക്കൂബ് (അ. സ.)-ഞാൻ അല്ലാഹുവോട് മാത്രമേ പരാതിപ്പെടുന്നുള്ളൂ.", "എൻ്റെ വേദനയെക്കുറിച്ചും ദുഃഖത്തെക്കുറിച്ചും ഞാൻ അല്ലാഹുവിനോട് മാത്രം പരാതിപ്പെടുന്നു.", "ആഴത്തിലുള്ള ദുഃഖത്തിലും വേർപിരിയലിലും.", "യൂസഫിൽ നിന്ന് വേർപിരിഞ്ഞപ്പോഴാണ് യാക്കൂബ് (അ. സ.) ഇത് പറഞ്ഞത്."),
        "dua_q_khayrun_hafiza" to DuaText("അല്ലാഹു ഏറ്റവും നല്ല രക്ഷകനാണ്.", "അല്ലാഹു ഏറ്റവും നല്ല രക്ഷകനും കരുണാനിധിയിൽ ഏറ്റവും കരുണാനിധിയുമായിരിക്കുന്നു.", "കുട്ടികളെയോ പ്രിയപ്പെട്ടവരെയോ ഒരു യാത്രയ്ക്ക് അയയ്ക്കുമ്പോൾ.", "മകനെ അല്ലാഹുവിന് സമർപ്പിക്കവേയാണ് യാക്കൂബ് (അ. സ.) ഇക്കാര്യം പറഞ്ഞത്."),
        "dua_q_aqraba_rashada" to DuaText("എൻ്റെ കർത്താവ് എന്നെ വലത്തോട്ട് കൂടുതൽ അടുത്ത് നയിക്കട്ടെ.", "ഒരുപക്ഷേ, എൻറെ രക്ഷിതാവ് എന്നെ ശരിയായ പെരുമാറ്റത്തിന് ഏറ്റവും അടുത്തുള്ളതിലേക്ക് നയിക്കും.", "ചില കാര്യങ്ങളിൽ ഒരു മികച്ച മാർഗം തേടുമ്പോൾ.", "നബി (സ) യോട് മറന്നുപോകുമ്പോൾ ഇത് പറയാൻ പറയപ്പെട്ടു."),
        "dua_q_sawa_as_sabil" to DuaText("മൂസയുടെ ദുആ (എ. എസ്)-എന്നെ ശരിയായ പാതയിലേക്ക് നയിക്കുക", "ഒരുപക്ഷേ എൻറെ രക്ഷിതാവ് എന്നെ ശരിയായ പാതയിലേക്ക് നയിക്കും.", "ഒരു പുതിയ യാത്രയിലോ അപരിചിതമായ റോഡിലോ പോകുമ്പോൾ.", "മദ്യാനിലേക്ക് തിരിഞ്ഞുകൊണ്ട് മൂസ (എ. എസ്) പറഞ്ഞു."),
        "dua_q_not_among_wrongdoers" to DuaText("എന്നെ തെറ്റുകാരുടെ കൂട്ടത്തിൽ ഉൾപ്പെടുത്തരുത്.", "എൻറെ രക്ഷിതാവേ, എന്നെ അക്രമികളായ ജനവിഭാഗത്തിൽ ഉൾപ്പെടുത്തരുത്.", "അക്രമികളിൽ നിന്ന് ഒരാളെ വേർപെടുത്താൻ അല്ലാഹുവിനോട് അഭ്യർത്ഥിക്കുന്ന ഒരു ദുആ.", "അക്രമികളിൽ നിന്ന് ഒരാളെ വേർപെടുത്താൻ അല്ലാഹുവിനോട് അഭ്യർത്ഥിക്കുന്ന ഒരു ദുആ."),
        "dua_q_do_not_make_us_trial" to DuaText("ഞങ്ങളെ ഒരു വിചാരണയാക്കരുത്.", "ഞങ്ങളുടെ രക്ഷിതാവേ, സത്യനിഷേധികൾക്ക് നീ ഞങ്ങളെ ഒരു പരീക്ഷണമാക്കി മാറ്റരുത്. ഞങ്ങളുടെ രക്ഷിതാവേ, നീ ഞങ്ങൾക്ക് മാപ്പ് നൽകുകയും ചെയ്യേണമേ. തീർച്ചയായും നീ പ്രതാപിയും യുക്തിമാനുമായിരിക്കുന്നു.", "ഇബ്രാഹിം (അ. സ.)-ന്റെയും കൂട്ടാളികൾക്കും നൽകിയ ദുആ.", "ഇബ്രാഹിം (അ. സ.)-ന്റെയും കൂട്ടാളികൾക്കും നൽകിയ ദുആ."),
        "dua_morning_witness" to DuaText("തൌഹീദിൻ്റെ പ്രഭാത സാക്ഷി", "അല്ലാഹുവേ, നിൻറെ സിംഹാസനവാഹകരേയും നിൻറെ മലക്കുകളെയും നിൻറെ സകല സൃഷ്ടികളെയും ഞാൻ രാവിലെ വിളിച്ചുകൊണ്ടിരിക്കുന്നു. നീ അല്ലാഹുവാകുന്നു എന്നും, നിന്നല്ലാതെ ഒരു ദൈവവുമില്ലെന്നും, നീ ഏകനും പങ്കാളിയല്ലെന്നും, മുഹമ്മദ് സൽമാൻ നിൻറെ ദാസനും ദൂതനും ആണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു.", "രാവിലെ നാല് തവണ പറഞ്ഞതായി വിവരണത്തിൽ പരാമർശിക്കുന്നു.", "രാവിലെ നാല് തവണ പറഞ്ഞതായി വിവരണത്തിൽ പരാമർശിക്കുന്നു."),
    )
}
